insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('b1work-grammar','Gdybym miał więcej czasu, ___ kurs zarządzania.','["ukończyłbym","ukończę by","ukończyłem"]',0,'Условное наклонение образуется формой прошедшего времени с частицей by: ukończyłbym.',0),
('b1work-grammar','Na pani miejscu ___ swoje osiągnięcia w CV.','["opisałabym","opisuję by","opisałam"]',0,'Na pani miejscu + tryb warunkowy служит вежливым советом.',1),
('b1work-grammar','Составьте: Я хотел бы узнать больше об обязанностях.','["Chciałbym dowiedzieć się więcej o obowiązkach.","Chcę się obowiązki więcej dowiedział.","Dowiedziałbym obowiązkom więcej."]',0,'Chciałbym — вежливая условная форма; dowiedzieć się o требует местного падежа.',2),
('b1work-grammar','Как официально попросить о встрече?','["Czy moglibyśmy umówić się na spotkanie?","Spotkamy się, dobra?","Musisz dać mi spotkanie."]',0,'Czy moglibyśmy... — нейтральная формальная просьба в условном наклонении.',3),
('b1work-grammar','Составьте: Если бы компания предложила обучение, я бы принял участие.','["Gdyby firma zaproponowała szkolenie, wziąłbym w nim udział.","Jeśli firma proponuje szkolenie, brałem go.","Gdyby szkolenie firma, wezmę udziałem."]',0,'Gdyby вводит условие, а wziąłbym — его возможный результат; wziąć udział w + miejscownik.',4),
('b1work-grammar','Uprzejmie ___ o informację na temat wyniku rekrutacji.','["proszę","żądam sobie","pytam tobie"]',0,'Uprzejmie proszę o... — стандартная формула официальной переписки.',5),
('b1work-quiz','Что означает stanowisko?','["должность","совещание","зарплата"]',0,'Stanowisko — место или должность в организации.',0),
('b1work-quiz','Do moich ___ należy przygotowanie raportów.','["obowiązków","awansów","zespołów do"]',0,'Należeć do + dopełniacz: do obowiązków.',1),
('b1work-quiz','Rekrutacja zwykle zaczyna się od ___.','["wysłania CV","wdrożenia terminu","osiągnięcia zespołu"]',0,'Кандидат начинает процесс с отправки резюме.',2),
('b1work-quiz','Gdybym dostała tę pracę, ___ się nowych narzędzi.','["nauczyłabym","nauczę by","uczyłam do"]',0,'Gdybym... nauczyłabym — согласованные формы условного наклонения.',3),
('b1work-quiz','Как вежливо начать просьбу о повышении зарплаты?','["Chciałbym porozmawiać o możliwości podwyżki.","Dajcie mi natychmiast podwyżkę.","Podwyżka należy mnie."]',0,'Chciałbym porozmawiać... звучит профессионально и не категорично.',4),
('b1work-quiz','Pracownik, który proponuje rozwiązanie bez polecenia, ___.','["wykazuje inicjatywę","dotrzymuje stanowiska","wdraża awans"]',0,'Wykazać inicjatywę — самостоятельно предложить или начать полезное действие.',5),
('b1work-quiz','Musimy ___ terminu do piątku.','["dotrzymać","osiągnąć się","awansować do"]',0,'Dotrzymać terminu — выполнить работу в установленный срок.',6),
('b1work-quiz','Szkolenie wspiera nasz ___.','["rozwój zawodowy","wynik rekrutacji do","obowiązek zespołem"]',0,'Обучение развивает профессиональные компетенции.',7),
('b1work-quiz','Czy ___ przesłać mi szczegóły oferty?','["mógłby Pan","Pan może by","musisz pan"]',0,'Mógłby Pan... — формальная вежливая просьба.',8),
('b1work-quiz','Po dobrych wynikach Marta otrzymała ___.','["awans","rekrutację","termin"]',0,'Otrzymać awans — получить повышение.',9),
('b1work-reading-check','Dlaczego Lena chciała zmienić pracę?','["Chciała się rozwijać i mieć większą odpowiedzialność","Nie lubiła swojego zawodu","Planowała przestać pracować"]',0,'Ей не хватало возможностей развития и ответственности.',0),
('b1work-reading-check','Co zrobiła przed wysłaniem CV?','["Opisała wyniki i ukończyła kurs","Poprosiła o natychmiastowy awans","Zrezygnowała ze szkolenia"]',0,'Она подготовила конкретные достижения и прошла курс.',1),
('b1work-reading-check','O co zapytał kierownik podczas rozmowy?','["O reakcję na opóźnienie projektu","O ulubiony środek transportu","O cenę mieszkania"]',0,'Руководитель попросил привести пример решения рабочей проблемы.',2),
('b1work-reading-check','Jak Lena odpowiedziała?','["Opisała plan i rozmowę z klientem","Obwiniła cały zespół","Powiedziała, że nie zna rozwiązania"]',0,'Она показала инициативу и спокойную коммуникацию.',3),
('b1work-reading-check','Jakie wsparcie rozwoju oferowała firma?','["Mentora i budżet szkoleniowy","Tylko wyższą pensję","Bezpłatne podróże"]',0,'В предложении были наставник и бюджет на обучение.',4),
('b1work-reading-check','Jaki jest główny wniosek tekstu?','["Rozwój wymaga przygotowania i świadomych pytań","Każda zmiana pracy gwarantuje awans","Na rozmowie nie warto pytać o warunki"]',0,'Лена добилась результата благодаря подготовке и оценке возможностей развития.',5);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values
('b1work-nowy-krok-leny','b1-work-development','Nowy krok Leny','Собеседование и осознанный выбор профессионального развития','B1',8,'💼','["Lena od czterech lat pracowała jako specjalistka do spraw obsługi klienta. Lubiła swój zespół i dobrze wykonywała obowiązki, jednak coraz częściej czuła, że stoi w miejscu. Chciała zdobyć nowe kwalifikacje, prowadzić projekty i mieć większy wpływ na decyzje.","Zanim wysłała CV, dokładnie opisała swoje wyniki i ukończyła internetowy kurs zarządzania projektem. Podczas rozmowy kwalifikacyjnej kierownik zapytał, co zrobiłaby, gdyby ważny projekt był opóźniony. Lena odpowiedziała, że najpierw ustaliłaby przyczynę, następnie przygotowałaby plan i spokojnie porozmawiałaby z klientem.","Podała też przykład z poprzedniej pracy. Gdy jej zespół nie mógł dotrzymać terminu, wykazała inicjatywę i podzieliła zadania inaczej. Dzięki temu projekt zakończył się tylko dzień później, a klient wcześniej otrzymał jasną informację. Kierownik docenił jej konkretne odpowiedzi.","Firma zaproponowała Lenie stanowisko koordynatorki, wsparcie mentora i budżet na szkolenia. Zanim przyjęła ofertę, uprzejmie zapytała o zakres obowiązków oraz możliwości awansu. Uznała, że rozwój zawodowy nie polega wyłącznie na zmianie stanowiska: wymaga przygotowania, odwagi i świadomego wyboru miejsca, w którym można się uczyć."]','{"specjalistka":{"lemma":"specjalistka","translation":"специалистка","part_of_speech":"существительное"},"wykonywała":{"lemma":"wykonywać","translation":"выполнять","part_of_speech":"глагол"},"wpływ":{"lemma":"wpływ","translation":"влияние","part_of_speech":"существительное"},"kwalifikacje":{"lemma":"kwalifikacja","translation":"квалификация","part_of_speech":"существительное"},"wyniki":{"lemma":"wynik","translation":"результат","part_of_speech":"существительное"},"opóźniony":{"lemma":"opóźniony","translation":"задержанный","part_of_speech":"прилагательное"},"ustaliłaby":{"lemma":"ustalić","translation":"установить; определить","part_of_speech":"глагол"},"przyczynę":{"lemma":"przyczyna","translation":"причина","part_of_speech":"существительное"},"dotrzymać":{"lemma":"dotrzymać","translation":"соблюсти","part_of_speech":"глагол"},"wykazała":{"lemma":"wykazać","translation":"проявить","part_of_speech":"глагол"},"docenił":{"lemma":"docenić","translation":"оценить по достоинству","part_of_speech":"глагол"},"zakres":{"lemma":"zakres","translation":"объём; круг","part_of_speech":"существительное"},"wyłącznie":{"lemma":"wyłącznie","translation":"исключительно","part_of_speech":"наречие"},"świadomego":{"lemma":"świadomy","translation":"осознанный","part_of_speech":"прилагательное"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29","comprehension_lesson_id":"b1work-reading-check"}',26,true)
